SELECT
    COUNT(DISTINCT CASE WHEN pre.ip IS NULL THEN cur.ip END) AS newUserCnt,
    COUNT(DISTINCT CASE WHEN pre.ip IS NOT NULL THEN cur.ip END) AS oldUserCnt
FROM (
    SELECT DISTINCT ip
    FROM t_link_access_log_stats
    WHERE full_short_url = #{fullShortUrl}
      AND create_time >= #{start}
      AND create_time  <=  DATE_ADD(#{end}, INTERVAL 1 DAY)
) cur
LEFT JOIN (
    SELECT DISTINCT ip
    FROM t_link_access_log_stats
    WHERE full_short_url = #{fullShortUrl}
      AND create_time < #{start}
) pre ON cur.ip = pre.ip

SELECT DISTINCT ip
FROM t_link_access_log_stats
WHERE

    full_short_url IN

        #{url}



    1=0

  AND ip IN

      #{ip}

  AND create_time < #{start}
LIMIT 1000
